"""Assembly-authored substance. Writes one expressly selected Record, never assigns authors."""
from pathlib import Path
import argparse, json, re, hashlib, sys
sys.dont_write_bytecode = True
TERM = Path(__file__).resolve().parents[1]
ALL = ['Stone-Zsela','Stevens',"O'Connor",'Scalia','Kennedy','Souter','Thomas','Ginsburg','Breyer']
ASSOC = ALL[1:]
FIVE = ['Stevens','Kennedy','Souter','Ginsburg','Breyer']
def names(xs): return ', '.join(xs[:-1])+' and '+xs[-1] if len(xs)>1 else xs[0]
def H(title, rule, authority, explanation):
 return f'### {title}\n\n**Holding and operative rule:** {rule}\n\n**Authority:** {authority}\n\n**Controlling explanation:** {explanation}'
D={}
D['venetie'] = dict(
 case='Alaska v. Native Village of Venetie Tribal Government', docket='No. 96-1577', date='1998-02-25', audit=1, slice='08_VENETIE',
 result='The Ninth Circuit is reversed, 9–0; the lands at issue are not a dependent Indian community and cannot support the asserted territorial tax.',
 event='Alaska v. Native Village of Venetie Tribal Government, No. 96-1577. Plenary merits decision, February 25, 1998; argued December 10, 1997. On writ of certiorari under 28 U.S.C. §1254(1) to the Ninth Circuit, 101 F.3d 1286. Review concerns whether the former Venetie Reservation lands conveyed under the Alaska Native Claims Settlement Act are a dependent Indian community under 18 U.S.C. §1151(b), supplying the territorial authority asserted for the nonmember school-construction tax. The District Court rejected that classification in Alaska’s action to enjoin collection; the Court of Appeals reversed.',
 action='The judgment of the Ninth Circuit is reversed.',
 judgment='**Reverse, 9–0.**\n\n**Supporting:** '+names(ALL)+'.\n\nThe lands at issue lack dependent-community status. The asserted territorial basis for the approximately $161,000 nonmember construction tax therefore fails. Further proceedings below must conform to that ruling; no new hearing, title adjudication or region-wide jurisdictional decree is ordered.',
 topology='{author} delivers the opinion of the Court, joined in full by {joiners}. All nine adopt both holdings and the bounded disposition. No separate writing issues.',
 holdings=[H('Dependent-community status requires a federal land relationship',
 'A dependent Indian community under 18 U.S.C. §1151(b) requires land set aside by the Federal Government for Indian use and federal superintendence over that community’s land relationship. Tribal recognition, Indian ownership and federal assistance to residents do not independently supply those territorial predicates.',
 'The unanimous Opinion of the Court directly adopts this rule; no fractured-opinion synthesis is involved.',
 'The Court reads the statutory category through Sandoval, which recognizes federal protection and supervision of Pueblo lands despite fee ownership, and McGowan, which treats a federal Indian-use set-aside under continuing supervision as Indian country. The rule does not require federal fee title, a reservation label or a prescribed administrative form. It does require the federal relationship those cases describe. Political dependence and territorial jurisdiction are distinct: Cherokee Nation and Worcester do not make every parcel owned by a federally recognized tribe Indian country. The Ninth Circuit’s six-factor approach cannot excuse the absence of either statutory predicate by balancing cohesiveness, government services and general dependence. Hagen and Yankton Sioux preserve the difference between title and territory; neither opening land nor fee ownership alone determines status.'),
 H('ANCSA removed both predicates from these lands',
 'These former-reservation lands, conveyed in unrestricted fee after ANCSA expressly revoked the reservation and without continuing federal supervision of their use or disposition, are not a dependent Indian community. The Tribe’s asserted territorial authority to tax this nonmember construction consequently fails.',
 'All nine join the Court’s complete statutory construction, application and geographic limit.',
 'ANCSA §1618(a) expressly revoked this reservation, §1603 extinguished aboriginal land claims, and the settlement authorized fee conveyances without continuing federal restrictions on transfer. The corporations’ §1618(b) election selected former-reservation land instead of monetary and other land benefits; it did not preserve the revoked reservation or impose a new Indian-use restriction. Their later conveyance to the Tribe likewise did not recreate a federal set-aside. Section 1636(d) protects land against adverse possession, real-property taxes and certain judgments while it remains unsold, unleased and undeveloped. Those conditional asset protections do not require federal approval of ordinary transfers or federal supervision of land use. Health, welfare, social and development programs benefit people without supplying the missing territorial supervision. The Tribe’s self-determination argument cannot substitute political recognition for the land relationship Congress ended. No allotment is at issue. The Court leaves other Native parcels, trust land, tribal identity, benefits, member-based powers and independently established consensual authority untouched.')],
 precedent='- Sandoval and McGowan supply the federal set-aside and supervision predicates; their allowance for nonfederal fee ownership remains intact.\n- Hagen and Yankton Sioux retain the operative-congressional-act inquiry and the distinction between title and territorial status; ANCSA’s express revocation and unrestricted settlement disposition supply the relevant change here.\n- Cherokee Nation and Worcester do not convert recognized political dependence into territorial jurisdiction over every tribal-owned parcel.',
 law='Section 1151(b) supplies no territorial tax authority on these former Venetie Reservation lands. The two-predicate rule governs dependent-community classification; it leaves the reservation and allotment categories distinct. No universal rule against tribal fee land, federal benefits or tribal government follows.',
 separate='',
 procedure='This Supreme Court review is complete. The Ninth Circuit’s contrary classification is reversed; implementation below must reject the asserted territorial tax basis consistently with this opinion. No private title, independent source of authority or different parcel is adjudicated.',
 sources='The land conveyance, tax dispute, ANCSA provisions and lower-court test are reported in [522 U.S. 520](https://www.govinfo.gov/content/pkg/USREPORTS-522/pdf/USREPORTS-522-520.pdf) and 101 F.3d 1286. The material statutory protections are conditional; no Indian allotment or other Alaska parcel is before the Court. The original petition, briefs and conveyance instruments are not separately reproduced; the decision rests on the published statutory and record recitations.',
 stone='The approved October 21, 2026 B supplement expressly supports reversal, both federal predicates and their absence under ANCSA, with other parcels, tribal identity, benefits and independently sourced powers reserved. All governing propositions fit that fixed core. Stone joins the whole opinion. No fallback, substantive narrowing, additional defense, or renewed approval is used.',
 continuity='No separate position or new open Supreme Court matter results. The dependent-community rule supplements, without altering, Hagen and Yankton Sioux. The same-day NCUA matter is not entering law.'
)
D['ncua'] = dict(
 case='National Credit Union Administration v. First National Bank & Trust Co. / AT&T Family Federal Credit Union v. First National Bank & Trust Co.', docket='Nos. 96-843 and 96-847', date='1998-02-25', audit=0, slice='07_NCUA',
 result='Affirmed in both dockets, 5–4; the banks may maintain APA review and the unrelated occupational-group policy exceeds the statute.',
 event='National Credit Union Administration v. First National Bank & Trust Co. and AT&T Family Federal Credit Union v. First National Bank & Trust Co., Nos. 96-843 and 96-847. Plenary merits decision, February 25, 1998; argued October 6, 1997. On writs of certiorari under 28 U.S.C. §1254(1) to the D.C. Circuit, 90 F.3d 525. The paired cases concern the banks’ right to seek APA review and whether §109 of the Federal Credit Union Act, 12 U.S.C. §1759, permits one federal credit union to add multiple unrelated occupational groups. The Court of Appeals allowed the challenge and rejected the agency’s construction after the District Court had sustained it.',
 action='The D.C. Circuit’s judgment is affirmed in both cases.',
 judgment='**Affirm in both dockets, 5–4.**\n\n**Supporting:** Stone-Zsela, Scalia, Kennedy, Thomas and Ginsburg.\n**Opposing:** Stevens, O’Connor, Souter and Breyer.\n\nThe challenged approvals cannot stand under the occupational common-bond provision. The existing appellate invalidation remains operative. The dissenters would vacate and remand for dismissal of this APA challenge on the statutory zone ground. No new member-removal order, liquidation, monetary award, transition date or enlarged injunction is entered.',
 topology='{author} delivers the opinion of the Court, joined in full by {joiners}. Its Article III, statutory-zone and occupational common-bond conclusions have those five direct joins. O’Connor dissents, joined by Stevens, Souter and Breyer, on the statutory zone of interests. The dissent reaches no common-bond merits question. No legislative-history rationale or conditional merits opinion is published.',
 holdings=[H('These banks may seek review of the membership expansion',
 'Directly competing banks injured by these completed charter approvals have Article III standing and fall at least arguably within the interests implicated by §109’s particular membership boundary for APA §702 review. They need not be the statute’s specially intended beneficiaries, but competitive injury alone does not establish a right to challenge every regulatory limitation.',
 'The five-Justice Opinion of the Court supplies direct authority for the provision-specific statutory-zone rule and its application.',
 'The approvals permit customers who otherwise might use the respondent banks to obtain services from ATTF; injury is undisputed, is traceable to the approvals and can be redressed by setting them aside. Lujan supplies the distinct constitutional elements, and Bennett requires examination of the particular provision rather than the Act’s general purpose. Section 109 limits credit-union membership and thus the customers the institution principally serves. These competitors challenge the agency’s expansion across that precise boundary. Clarke and Data Processing permit that direct statutory connection without a special-beneficiary requirement. Air Courier separately requires a statutory interest beyond injury, but its collateral employment interests differ from this challenge by participants in the regulated customer market. The Court does not find that protecting bank profits was Congress’s purpose. Nor does it eliminate APA finality, adequate-remedy, preclusion or other applicable conditions; these completed, operative approvals present no established independent defect of that kind.'),
 H('Unrelated occupational groups cannot replace the common bond',
 'Section 109’s occupational route requires a common occupational bond connecting the membership of the occupationally defined credit union; it does not authorize aggregation of unrelated employer groups merely because each has its own internal bond. The challenged agency policy crosses that statutory boundary and receives no deference at Chevron’s first step.',
 'The same five Justices adopt the common text-and-structure rationale, its application and limits.',
 'The sentence limits federal credit-union membership, not merely the labels assigned to each component group. The plural groups permits multiple groups sharing a common occupational bond; it does not make a succession of unrelated bonds sufficient. The agency’s reading retains internal group and service-area conditions, but those are different from the connection Congress imposed on the membership. The parallel geographic alternative supports that reading. NCUA’s concession that the geographic groups must occupy the same defined community is an attributed argument, not a separate holding on geographic charters. MCI requires enforcement of an enacted boundary before deference. NationsBank permits reasonable financial classifications within an authorized domain and does not permit removal of its boundary. General rulemaking authority, serviceability and administrative efficiency cannot replace the required bond. A changed interpretation is not invalid merely because it changed. The decision imposes no single-employer requirement and does not determine the full breadth of a genuine occupation or association, geographic charters, or individual membership-retention rights.'),
 H('The disposition enforces the challenged boundary without rewriting membership law',
 'The statutory invalidation applies to the challenged unrelated employer-group additions; the other membership commands and permissions in §1759 remain intact. Affirmance supplies no independent enlargement of the injunction reported below.',
 'The same five-Justice opinion adopts this scope of construction and relief.',
 'Section 1759 permits elected persons and organizations within Board rules, subject to the statutory membership limitation, and requires each member to subscribe to at least one share and pay its initial installment. A uniform entrance fee is required only if the board of directors requires it. The distinct final sentence permits survivorship joint-tenancy shares with a member’s designated person; that person may not vote, obtain loans or hold office unless within the field of membership and a qualified member. The joint-tenancy permission is not unlimited membership or authority to add unrelated employer groups. None of those provisions is displaced. The Court resolves the challenged legal interpretation, not every approval condition or remedial detail. Future applications remain subject to the statutory limits then lawfully governing them.')],
 precedent='- Lujan preserves injury, traceability and redressability as separate constitutional requirements.\n- Bennett is applied to the interests arguably protected by the particular provision and preserves APA review conditions.\n- Clarke and Data Processing supply the permissive, provision-connected competitor inquiry without a special-beneficiary requirement.\n- Air Courier preserves the distinction between injury and the statutory zone; its derivative employment interest is distinguished.\n- Chevron requires enforcement of the unambiguous statutory boundary before agency deference.\n- MCI applies the prohibition on eliminating an enacted requirement through interpretation. NationsBank’s lawful-classification holding remains intact within statutory boundaries.',
 law='The banks’ APA action may proceed, and the challenged unrelated occupational-group construction is invalid. The decision neither abolishes statutory-zone screening nor requires Congress to have enacted the FCUA especially to protect banks. It supplies no general ban on multiple employers sharing a genuine common occupation, no geographic-charter ruling and no rule invalidating administrative change as such.',
 separate='**O’Connor, joined by Stevens, Souter and Breyer, dissenting.** The dissent accepts the banks’ concrete economic injury and rejects any requirement that Congress expressly identify them as special beneficiaries. It nevertheless finds their asserted protection against competition only incidental to §109. The common-bond rule organizes a cohesive cooperative; it does not keep credit unions collectively out of an identifiable market, since a group may join another qualifying union or form one. Clarke’s permissive inquiry and Bennett’s provision-specific focus therefore do not reduce to the economic effect of enforcing any restriction. Air Courier preserves the need for this additional statutory relationship. The dissent would vacate the reviewed judgment and remand for dismissal of the APA action, removing relief dependent on it without approving the agency’s interpretation or denying Article III injury.',
 procedure='Review of both dockets is complete. The D.C. Circuit’s invalidation stands, and the agency must act consistently with the occupational common-bond limitation. The Court enters no new remedial program and decides no individual member’s status.',
 sources='The administrative policies, litigation history, specific geographic concession and undisputed competitive injury are reported in [522 U.S. 479](https://www.govinfo.gov/content/pkg/USREPORTS-522/pdf/USREPORTS-522-479.pdf). The governing membership text appears in the [1997 United States Code, 12 U.S.C. §1759](https://www.govinfo.gov/content/pkg/USCODE-1997-title12/pdf/USCODE-1997-title12-chap14-subchapI-sec1759.pdf). The reported nationwide injunction’s full wording is not separately available here; no omitted condition or enlarged remedy is inferred. The District Court’s statement that second-step reasonableness was not seriously disputed is not a universal waiver or an independent finding by this Court.',
 stone='The October 21, 2026 approved supplement permits review based on the precise membership/market connection and affirms invalidation of unrelated occupational-group additions. The full rationale preserves those limits and adopts no legislative-purpose fact, single-employer rule, associational/geographic restriction or expanded injunction. Stone joins in full. No standing fallback is used. The four threshold dissenters’ conditional merits preferences remain unadopted; adding Stone to the four actual affirmers creates the actual five-Justice coalition without changing any Associate commitment.',
 continuity='O’Connor’s published threshold dissent, joined by Stevens, Souter and Breyer, retains the provision-protection versus incidental-competition distinction described in Separate Writings. Conditional merits selections in the frozen handoff are not public opinions or law. The same-day Venetie decision supplies no entering-law premise.'
)
D['aponte'] = dict(
 case='Aponte Matos v. Toledo Dávila', docket='First Circuit No. 97-1645', date='1998-02-26', audit=2, slice='09_APONTE',
 result='The First Circuit’s reviewed disposition is affirmed, 9–0, preserving the Laboy fabrication remand and the distinct grounds governing all other components.',
 event='Aponte Matos v. Toledo Dávila, First Circuit No. 97-1645, 135 F.3d 182. Plenary merits decision on submission, February 26, 1998. On review under 28 U.S.C. §1254(1) of the First Circuit’s February 3, 1998 judgment in the plaintiffs’ appeal from final summary judgments. The questions concern a warrant affiant’s alleged material fabrication, other defendants’ responsibility, search execution and the separately preserved appellate components. The action seeks damages under 42 U.S.C. §1983 against Puerto Rico officials and under Bivens and §1331 against federal officials. No separate Supreme Court docket or oral-argument date is assigned. The lower-court argument on December 3, 1997 is not an argument before this Court.',
 action='The reviewed appellate disposition is affirmed, preserving reversal of summary judgment on the material-fabrication claim against Laboy and remand of that claim.',
 judgment='| Component | Disposition and vote | Supporting Justices | Remedy and basis |\n|---|---|---|---|\n'
 '| Laboy’s material-affidavit-fabrication claim | Affirm the First Circuit’s reversal of summary judgment, 9–0 | '+names(ALL)+' | Preserve the ordinary factual remand; no liability finding |\n'
 '| Other officers’ participation; timely scope, announcement and force claims; Puerto Rico supervision | Affirm the distinct defense dispositions, 9–0 | '+names(ALL)+' | Lack of supported personal involvement or the particular conduct-date immunity grounds described below |\n'
 '| Plichta computer-access and federal supervisor Ilario components | Sustain appellate nonreview, 9–0 | '+names(ALL)+' | Untimely appeals from separately final judgments; no merits endorsement |\n'
 '| Counsel access and requested compulsory supplemental jurisdiction | Preserve waiver and reject compulsory retention, 9–0 | '+names(ALL)+' | No counsel-right holding; a proper discretionary state-claim request remains possible |\n\n'
 'Stone-Zsela agrees with the dispositions without joining the complete retained-immunity reasoning. His agreement concerning appellate nonreview of the Plichta and Ilario judgments, counsel-access waiver and the request to compel supplemental jurisdiction supplies no additional ground.',
 topology='| Writing | Author | Joined by | Relationship to judgment | Scope joined |\n|---|---|---|---|---|\n'
 '| Opinion of the Court | {author} | {joiners} | Affirms the reviewed component dispositions | All eight Associate Justices join all holdings, with the distinct procedural and immunity grounds preserved |\n'
 '| Same opinion, partial joins | {author} | Stone-Zsela | Agrees with every disposition | Joins the deliberate-falsehood application of Holding 1 and Holding 2’s personal-responsibility ground; not the complete knowing-or-reckless rule, retained-immunity explanation or procedural rationales |\n'
 '| Concurrence in part and in the judgment | Stone-Zsela | — | Agrees with every disposition | Preserves his distinct defense position without an additional ground for the identified procedural components |',
 holdings=[H('A material fabrication dispute cannot be resolved by relying on the warrant it produced',
 'An officer’s personally responsible knowing or reckless falsehood material to probable cause cannot obtain qualified immunity merely from the warrant that deception procured. Competent conflicting sworn accounts of the essential observation require ordinary factual resolution; negligence, a failed search or ulterior purpose alone does not establish this claim.',
 'The Court opinion, joined by all eight Associate Justices, directly adopts the complete rule and this summary-judgment application. Stone-Zsela joins the deliberate-falsehood application, without joining the complete knowing-or-reckless and retained-immunity rationale.',
 'Franks requires culpable material falsehood; Malley prevents judicial issuance from automatically insulating the responsible officer. Clanton preserves both propositions and the corrected-affidavit inquiry. Laboy asserted that he saw two men exchange a firearm and enter the house. The resident swears that no man entered then, and her husband supports her account that he was elsewhere. The other officer reports what Laboy told him rather than an independent observation. This evidence presents a credibility dispute about the asserted observation necessary to probable cause; it is not merely an inference from an empty search. The Court assumes the competent plaintiff-favorable account for summary judgment without finding a lie. Crawford-El retains ordinary proof rather than an enhanced motive threshold. The alleged fabrication must still be proved, together with materiality, responsibility, causation and injury. No liability, damages, mandatory trial or automatic discovery entitlement follows.'),
 H('Each defendant must be connected to the asserted constitutional wrong',
 'Participation in a later search or supervisory rank alone does not establish responsibility for an affiant’s fabrication. Summary judgment stands where the supported record supplies no knowledge, assistance, agreement or affirmative causal link connecting the other officers or Puerto Rico supervisors to the alleged falsehood.',
 'All nine Justices join this severable personal-responsibility ground and its record application.',
 'The other officers’ presence supplies no evidence that they knew of, helped create or agreed to the alleged invention. The monthly warrant expectation and remote judicial criticism of Laboy do not establish a supervisor’s encouragement, acquiescence or deliberate indifference to this alleged deception. Fletcher separates actual evidentiary conduct from official role; Crawford-El preserves personal responsibility and causation. These principles reject collective liability without immunizing knowing assistance or a supported supervisory wrong in a different record. The disposition concerning federal supervisor Ilario rests instead on the untimely appeal, not these merits grounds.'),
 H('The timely execution claims fail on their own record and conduct-date grounds',
 'Qualified immunity on the timely search-scope, announcement and force components is sustained under the law and information relevant to December 6, 1993, without deciding that every challenged act was constitutional. Neither a Supreme-Court-only notice rule nor a physical-injury prerequisite governs.',
 'All eight Associates join these distinct applications of the retained Harlow/Anderson defense.',
 'Garrison and Ross confine the weapons search to places capable of containing the authorized objects; no evidence identifies a search beyond that scope. Uncompelled questions about money do not establish the claimed clearly unlawful expansion and authorize no unrestricted money search. On announcement, the supported preconduct legal setting left reasonable uncertainty concerning this entry’s constitutional requirement. Elder requires all relevant pre-existing law, and Lanier permits obvious coverage without a factual twin; later Wilson and Richards do not themselves provide 1993 notice. The ultimate reasonableness of the unannounced entry remains open. Graham governs force from the contemporary security perspective. The ax entry, officers, dogs and blockade formed an active weapons search; the reported conduct inside was orderly. Assuming that Colón pointed his gun and threatened the returning daughter who insisted on passing the blockade, this record does not establish conduct plainly outside the latitude allowed by 1993 law. Smith concerned considerable force against a wholly unresisting arrestee and does not turn injury into a necessary element. The security context, not the absence of touching alone, supports this immunity result. No universal permission to threaten a person follows.'),
 H('Appellate nonreview, waiver and supplemental jurisdiction retain distinct consequences',
 'The untimely appeals from the separately final Plichta and Ilario judgments do not permit review of their merits, and the undeveloped counsel-access claim remains waived. Survival of the federal fabrication claim does not compel the District Court to exercise supplemental jurisdiction over state claims; a proper discretionary request remains available.',
 'The eight-Justice Court opinion adopts these grounds. Stone-Zsela agrees only with these dispositions and adds no rationale.',
 'The reported Rule 54(b) judgments were entered May 29 and July 22, 1996; the May 5, 1997 notice came after the applicable 60-day period. The computer component therefore supplies no holding that an unsuccessful attempt to access files cannot be a search, and the federal-supervisor component supplies no supervisory-merits ruling. Counsel access was not specifically developed on appeal. Section 1367 and City of Chicago keep supplemental power separate from discretionary retention: remand of one federal claim does not determine state claims against every defendant. This is the plaintiffs’ appeal from final judgments, so Johnson and Behrens’ limitation on officers’ interlocutory factual appeals does not bar ordinary final-judgment evidentiary review. The Court neither compels retention nor directs dismissal of every state claim.')],
 precedent='- Franks and Malley are applied to personally responsible, culpable material affidavit falsehoods; judicial issuance is not categorical protection.\n- Clanton supplies the same bounded material-deception rule and preserves corrected truthful probable cause and all liability predicates.\n- Harlow and Anderson retain particularized, objective conduct-date immunity. Elder requires all relevant existing law; Lanier explains obvious coverage without supplying retrospective notice.\n- Graham governs force; Smith is distinguished on the whole security record, preserving its rejection of a factually identical precedent requirement.\n- Garrison and Ross retain object-based limits on a premises search.\n- Crawford-El preserves ordinary proof, and Fletcher preserves responsibility for personal evidentiary acts; neither establishes liability here.\n- Johnson and Behrens concern interlocutory review and do not remove this final-judgment appellate jurisdiction.\n- City of Chicago preserves the distinction between supplemental power and discretionary retention. Wilson and Richards supply no retroactive notice for the 1993 conduct.',
 law='The surviving fabrication claim returns for ordinary proceedings under Franks, Malley, Clanton and the retained immunity framework. No contextual-defense replacement, heightened motive proof, collective responsibility, universal physical-injury rule or Supreme-Court-only notice rule is adopted. The separate nonreviewed and waived matters remain outside the merits decision.',
 separate='**Stone-Zsela, concurring in part and in the judgment.** Stone-Zsela joins the Court’s deliberate-falsehood application and independent personal-responsibility ground. Intentional creation of facts material to a warrant’s justification cannot be reasonable reliance on that warrant, but the alleged lie and its materiality must be proved: an empty search is not proof of fabrication. Other officers and supervisors require evidence of their own knowledge, assistance or independent violation, and scope or execution objections require a supported invasion. He preserves his objection to treating a deliberate violation as a reasonable mistake under a duplicative official excuse, without converting his proposed contextual defense into the Court’s governing rule or joining its complete immunity rationale. Failure of a defense does not establish a violation, causation, damages, supervisory responsibility or entitlement to trial. He adds no reason for the procedural dispositions identified in the judgment.',
 procedure='The First Circuit’s disposition stands: only the surviving Laboy material-fabrication claim returns for ordinary proceedings on the present federal claim map. The separate final judgments, appellate waiver and distinct defense rulings remain intact. A proper request concerning supplemental state claims may be considered under the applicable discretion; no particular result, hearing, discovery schedule, trial or damages is ordered. This Supreme Court review is complete.',
 sources='The complete lower opinion, [135 F.3d 182](https://static.case.law/f3d/135/html/0182-01.html), supplies the sworn-account recitations, individual claim map, December 1993 conduct and separately final judgments; [Public.Resource](https://law.resource.org/pub/us/case/reporter/F3/135/135.F3d.182.97-1645.html) provides a cross-check. Original declarations, the full appendix, Rule 54(b) orders and appeal notices are not separately reproduced. Their published recitations support the bounded dispositions; no additional testimony, default or concession is inferred. No independent warrant based on Plichta’s separate information is adjudicated.',
 stone='The approved supplement’s reverse-summary-judgment shorthand refers to Laboy’s District Court judgment. The reviewed First Circuit already reversed that component, so affirming that reviewed result preserves the exact approved relief without changing the fixed core. Stone joins Holding 1’s deliberate-falsehood application and Holding 2’s independent personal-responsibility ground, both expressly supported by his approved core. He does not join the complete knowing-or-reckless rule or the retained-immunity reasoning and concurs separately in part and in the judgment. The standing fallback supplies only votes on A3 Plichta appellate nonreview, A4 Ilario appellate nonreview, A9 counsel-access waiver and A10 compulsory supplemental-jurisdiction request. No fallback alters his stated affiant, remaining-claims or remand positions. He does not author the complete Court rationale; his express contextual-defense proposal is noncontrolling and no unsupported elements or burden are added.',
 continuity='The only material published separate position is Stone-Zsela’s concurrence, fully stated in Public Projection. It preserves the deliberate-deception/individual-responsibility position and objection to a duplicative excuse without a new Court defense. Ordinary proceedings remain below, not a stopped Supreme Court matter.'
)
D['shahar'] = dict(
 case='Shahar v. Bowers', docket='Eleventh Circuit No. 93-9345', date='1998-03-02', audit=3, slice='10_SHAHAR',
 result='Defense summary judgment is vacated on the four preserved claims and remanded with distinct association, free-exercise and ordinary-equality instructions; Stone reaches only equal protection on a separate proposed standard.',
 event='Shahar v. Bowers, Eleventh Circuit No. 93-9345, 114 F.3d 1097 (en banc). Plenary merits decision on submission, March 2, 1998. On review under 28 U.S.C. §1254(1) of the May 30, 1997 judgment affirming summary judgment for Bowers. The case concerns withdrawal in July 1991 of an accepted civilian staff-attorney offer because of a planned same-sex religious commitment ceremony. The preserved theories are intimate association, expressive association, free exercise and equal protection. Shahar seeks damages and injunctive employment relief. No separate Supreme Court docket or oral-argument date is supplied; substantive due process and an independent free-speech claim are outside this review.',
 action='The defense judgment is vacated on the four preserved claims and the case remanded for the distinct inquiries stated in the Court’s opinion.',
 judgment='| Claim | Disposition and vote | Supporting Justices | Opposing Justices | Position of Stone-Zsela |\n|---|---|---|---|---|\n'
 '| Intimate association | Vacate and remand, 5–3, with one not reaching the claim | Stevens, Kennedy, Souter, Ginsburg, Breyer | O’Connor, Scalia, Thomas | Does not reach this claim |\n'
 '| Expressive association | Vacate and remand, 5–3, with one not reaching the claim | Stevens, Kennedy, Souter, Ginsburg, Breyer | O’Connor, Scalia, Thomas | Does not reach this claim |\n'
 '| Free exercise | Vacate and remand, 6–2, with one not reaching the claim | Stevens, O’Connor, Kennedy, Souter, Ginsburg, Breyer | Scalia, Thomas | Does not reach this claim |\n'
 '| Equal protection | Vacate and remand: 5; reverse and remand: 1; affirm: 3 | Stevens, Kennedy, Souter, Ginsburg and Breyer support vacatur; Stone-Zsela supports reversal | O’Connor, Scalia, Thomas support affirmance | Would reverse and remand for intermediate scrutiny; the five-Justice vacatur and controlling instruction apply ordinary rationality |\n\n'
 'Stone-Zsela’s nonreach is a limitation of his decision, not nonparticipation or a vote affirming the other claims. Each remanded claim has its own direct majority. No final liability, immunity, reinstatement, backpay, damages or compulsory trial is ordered.',
 topology='| Writing | Author | Joined by | Relationship to judgment | Scope joined |\n|---|---|---|---|---|\n'
 '| Opinion of the Court | {author} | {joiners} | Vacates and remands all four claims | Parts I (association), II (free exercise), III (equal protection) and IV (bounded mandate) have Stevens, Kennedy, Souter, Ginsburg and Breyer; O’Connor also joins Part II and Part IV only as applied to the free-exercise remand |\n'
 '| Concurrence in setting aside the equality judgment and remanding; dissent from formal vacatur and the ordinary-rationality mandate | Stone-Zsela | — | Would reverse that claim and remand under intermediate scrutiny | Does not join the Court’s formal equality disposition or mandate, its ordinary-rationality reasoning, or reach the association/free-exercise claims |\n'
 '| Opinion concurring in part and dissenting in part | O’Connor | — | Joins the free-exercise remand; would sustain association and equality judgments | Particular professional employment balance and ordinary rationality |\n'
 '| Dissent | Scalia | Thomas | Would affirm all four claims | Assumed-right employment balance, secular-ground free-exercise analysis and ordinary rationality |',
 holdings=[H('I. Private association requires its own protection and employment inquiry',
 'The actual selective, enduring intimate relationship and its religious expression cannot be denied constitutional protection merely because they lack civil-marriage recognition or include an invitation-only ceremony. A public employer’s genuine operational interests remain relevant, but generalized forecasts, presumed lawbreaking and presumed government endorsement do not conclusively justify this defense summary judgment.',
 'Part I of the Court’s opinion is joined by Stevens, Kennedy, Souter, Ginsburg and Breyer, five direct votes.',
 'Roberts and Rotary distinguish close personal association from association for protected expression and require examination of the actual relationship and activity. On the plaintiff-favorable record, the selective, enduring relationship and its religious expression satisfy those protected predicates; their protection is not left open merely because the relationship lacks civil-marriage recognition. Shahar seeks protection against an employment penalty, not marital status or benefits. Umbehr separates entitlement to a benefit from an unconstitutional reason for withholding it. Jeffries requires attention to actual functions and institutional needs: prevention need not await disruption, but a reasonable forecast does not alone settle the legality of penalizing protected activity. Confidentiality, credible representation, assignment flexibility and professional trust remain substantial concerns. Neither a general office label nor speculation about endorsement establishes inability to perform lawful duties. No lawbreaking or refusal of duties is established, and later insurance or name-change evidence cannot supply contemporaneous knowledge. Waters protects reasonable factual reliance only when the substantive rule permits disciplining the conduct described and establishes no universal interview requirement. The remaining employment justification, causal application and relief return for adjudication; the Court orders no retention of a lawyer unable to perform necessary work.'),
 H('II. Free exercise cannot be absorbed into a general employee-speech balance',
 'A public-employment decision alleged to burden sincere private religious exercise must be examined for neutrality and general applicability under its own governing rule. If the actual restriction is nonneutral or not generally applicable, the employer must establish a compelling justification and narrow tailoring; religious impact alone does not establish that trigger.',
 'Part II has Stevens, O’Connor, Kennedy, Souter, Ginsburg and Breyer, six direct joins.',
 'Smith preserves neutral, generally applicable rules. Lukumi requires examination of objective targeting and comparable secular conduct; Brown applies the required justification to religion-specific employment restrictions while preserving control of work, resources, coercion and official representation. The lower court assumed religious protection and treated the claim as resolved by the same general employment balance. That does not answer whether this withdrawal imposed the prohibited religious disability. The contrary argument is substantial: Bowers may have responded to the represented relationship and perceived job consequences regardless of religious form. That is an argument requiring proper assessment, not an established hypothetical fact that disposes of the independent claim. Sincerity does not prove targeting, and the absence of theological compulsion does not defeat sincere exercise. All six joiners reserve the trigger’s ultimate application and any properly supported justification. No finding of discrimination, general religious exemption or new statutory claim follows.'),
 H('III. The actual equality disadvantage requires ordinary constitutional justification',
 'An adverse civilian employment classification does not escape ordinary equal-protection review by being described as conduct-based or as a hiring choice. The actual disadvantage must bear a rational relation to a legitimate governmental interest; no new orientation-based heightened tier is adopted.',
 'Part III has Stevens, Kennedy, Souter, Ginsburg and Breyer, five direct joins. Stone-Zsela’s different proposed scrutiny standard is not controlling and is not combined with this rationale.',
 'Romer applies ordinary rationality to the actual disability, allowing reasonable predictions and generalizations while excluding bare harm or irrational prejudice. Valot distinguishes that inquiry from justification for penalizing protected activity and from a proved same-decision defense. The lower court’s conduct/employment characterization cannot itself resolve the claim. The office’s professional and representative responsibilities remain legitimate considerations; remand does not make every predictive judgment invalid or require proof of actual disruption. Walmer, Thomasson and Richenberg address military and conduct-related settings, not an irrebuttable civilian inference from a religious commitment ceremony. Bowers v. Hardwick concerns its specified conduct; orientation or the ceremony alone proves no violation. The Court neither decides liability nor requires intermediate scrutiny. The five-Justice ordinary-rationality instruction governs the equality remand.'),
 H('IV. Causation, conduct-date immunity and relief remain independent',
 'Remand requires claim-specific constitutional predicates, personal responsibility, causation and lawful relief. Where retaliation analysis applies, protected activity must be a substantial or motivating factor and a same-decision defense requires proof by a preponderance; ordinary rationality’s conceivable basis is not that proof.',
 'Part IV is joined by the five common Court-opinion Justices; O’Connor joins its application to the free-exercise remand.',
 'Umbehr and Jeffries preserve actual causal responsibility and the counterfactual defense. Bowers pleaded qualified immunity, but neither lower court decided it and he did not request appellate affirmance on that ground. The Court does not award the defense, decide waiver or automatically revive it. Any procedurally available personal-damages defense concerns notice in July 1991; later Romer, Brown, Umbehr, Jeffries, Valot and Danahy cannot supply retrospective notice. Prospective relief, any proper successor, personal damages and official-capacity relief retain separate predicates. Later evidence may have a lawful remedial relevance without becoming contemporaneous motive. Elapsed time establishes neither mootness nor a continuing job entitlement. The mandate compels no interview, discovery plan, trial, reinstatement, backpay, fees or damages award.')],
 precedent='- Roberts and Rotary supply distinct intimate- and expressive-association inquiries; civil-marriage recognition is not their exclusive boundary.\n- Umbehr distinguishes benefit entitlement from unconstitutional retaliation and preserves actual causation and the preponderance same-decision defense.\n- Jeffries preserves preventive employment judgment while rejecting conclusive reliance on generalized forecasts. Waters protects reasonable factual reliance only within the substantive constitutional rule; neither supplies a compulsory interview code.\n- Smith retains neutral, generally applicable rules; Lukumi supplies objective targeting, comparable secular conduct and triggered strict justification. Brown requires the separate religion-specific employment inquiry.\n- Romer supplies ordinary rationality for the actual disadvantage. Valot keeps that standard distinct from a protected-right penalty and a same-decision defense.\n- Walmer, Thomasson and Richenberg retain their military and conduct-related scope; they do not establish civilian exclusion or a heightened orientation tier. Bowers v. Hardwick is not extended from specified conduct to orientation or a ceremony.\n- Danahy supplies no office-wide merits exception and no retroactive July 1991 notice. NTEU’s broad prospective-restraint burden is not transferred wholesale to this single hiring decision.',
 law='The four preserved claims return under distinct constitutional standards. Five Justices establish the association and ordinary-equality grounds; six establish the separate free-exercise inquiry. Intermediate scrutiny is not adopted. No unified rationale is synthesized from different writings, and no military inference, generalized government-lawyer exception or actual-disruption prerequisite controls civilian employment.',
 separate='**Stone-Zsela, concurring in setting aside the equal-protection judgment and remanding, and dissenting from formal vacatur and the ordinary-rationality mandate.** Stone-Zsela would reverse the equality judgment and require intermediate scrutiny on a developed record. He treats that standard as a proposed change, not a rule already established by Romer, Walmer or Thomasson. The actual reason for withdrawing the offer, any unsupported hostility and legitimate civilian operational grounds require examination; military conduct-related precedents do not settle this religious commitment ceremony. He leaves intimate association, expressive association and free exercise unresolved, as well as liability, immunity, damages and ultimate relief.\n\n**O’Connor, concurring in part and dissenting in part.** O’Connor joins the separate free-exercise inquiry under Brown and Lukumi without finding targeting. On association she assumes the asserted protection but gives dispositive weight to this staff lawyer’s professional trust, representation, assignment flexibility and credible forecasts, as in her Jeffries position and Waters rationale. On equality she finds a sufficient ordinary-rationality relationship to those professional concerns without military deference or a new classification tier. She would sustain those three dispositions while allowing only the religion claim to return; she infers neither sodomy nor refusal to perform duties.\n\n**Scalia, joined by Thomas, dissenting.** The dissent assumes the association rights for decision and finds the particular legal office’s preventive professional judgment sufficient; it adopts no categorical immunity for government lawyers or license for bare hostility. On free exercise it reads the supported decision as responding to the represented relationship and perceived work consequences, regardless of religious form, and distinguishes Brown’s direct religion-specific commands. Smith and Lukumi forbid religious discrimination but do not convert every effect on religious exercise into prohibited targeting. The dissent also finds the particular professional concerns sufficient under ordinary rationality. It would affirm without a damages-immunity ruling or a finding that the ceremony proves unlawful sexual conduct.',
 procedure='The case returns for the four claim-specific inquiries and properly remaining defenses and remedies. The judgment supplies no final employment entitlement, personal liability or constitutional damages. No additional speech or substantive-due-process claim is revived. This Supreme Court review is complete.',
 sources='The record, competing en banc accounts and preservation limits appear in [114 F.3d 1097](https://static.case.law/f3d/114/html/1097-01.html), with a [Public.Resource cross-check](https://law.resource.org/pub/us/case/reporter/F3/114/114.F3d.1097.93-9345.html). The published accounts conflict on the precise ceremony date; none of the holdings depends on selecting one or finding the ceremony occurred before withdrawal. Depositions and the application are available here only through published recitations. Later-acquired facts do not establish contemporaneous knowledge. The March 2 merits submission supplies the decisional placement; no additional historical docket or argument date is asserted.',
 stone='The October 21, 2026 supplement expressly proposes reversing and remanding equal protection under intermediate scrutiny on a developed record. It expressly leaves intimate association, expressive association and free exercise unresolved. Stone accordingly takes no position disposing of those three claims, does not join their holdings and does not use standing fallback. His equality vote joins setting aside the defense judgment and remanding, while his formal preference for reversal and proposed scrutiny remain distinct from the five-Justice vacatur/ordinary-rationality mandate. This preserves the approved choice without supplying a missing substantive vote. His equality-only concurrence performs necessary legal work. He is not an eligible author of the shared Court rationale.',
 continuity='All material published noncontrolling grounds are in the three separate-writing summaries in Public Projection, with exact joins. The proposed intermediate tier remains Stone-only. O’Connor’s association/equality sustaining grounds and Scalia/Thomas’s additional secular-ground free-exercise position remain distinct. Each component has a direct majority without Stone’s expressly withheld decision; no Marks inquiry or frozen commitment revision is used.'
)
D['bogan'] = dict(
 case='Bogan v. Scott-Harris', docket='No. 96-1569', date='1998-03-03', audit=4, slice='13_BOGAN',
 result='Reversed, 9–0; the two officials have absolute legislative immunity from the reviewed individual damages claims.',
 event='Bogan v. Scott-Harris, No. 96-1569. Plenary merits decision, March 3, 1998; argued December 3, 1997. On writ of certiorari under 28 U.S.C. §1254(1) to the First Circuit. The Court reviews personal damages judgments under 42 U.S.C. §1983 against Fall River’s mayor and city-council vice president for introducing, approving and signing the ordinance abolishing Scott-Harris’s department. The question is whether those acts receive absolute legislative immunity despite the retaliatory motive found by the jury. Only Bogan and Roderick petition; the city judgment, which the Court of Appeals set aside, is not restored.',
 action='The judgment sustaining the two individual damages judgments is reversed.',
 judgment='**Reverse, 9–0.**\n\n**Supporting:** '+names(ALL)+'.\n\nBogan and Roderick receive absolute legislative immunity for the challenged legislative acts. The reviewed personal damages claims must be disposed of consistently with that immunity. No new factfinding mandate, municipal immunity, reinstatement of the city verdict or ruling on prospective relief follows.',
 topology='{author} delivers the opinion of the Court, joined in full by {joiners}. All nine adopt the functional immunity rule and its application to both officials. No separate writing issues.',
 holdings=[H('Local legislative work receives absolute personal damages immunity',
 'Local officials performing genuine legislative functions have absolute immunity from personal damages under §1983 for those acts. The protection follows the function, so an executive official participating in that legislative process receives it for legislative work without immunity for all executive conduct.',
 'The unanimous Opinion of the Court directly adopts the rule and the distinction between function and title.',
 'Tenney protects legislative independence against damages litigation over legitimate legislative activity. Lake Country Estates establishes that the institutional justification does not disappear below the state legislature. Local scale likewise does not remove the need to deliberate and enact policy without personal damages exposure. Antoine requires historical and functional support rather than immunity based on importance or title; that support exists for the lawmaking process. Consumers Union recognizes that executive participation in legislative work can carry the corresponding immunity. The historical municipal-liability examples do not establish an exception for these particular lawmaking functions merely because municipal officials were defendants. The Court decides personal damages immunity for the acts before it, not municipal liability or every form of prospective relief.'),
 H('This budget ordinance is legislative in substance and form',
 'Roderick’s committee work and vote, and Bogan’s introduction of the budget and signature on the abolition ordinance, are legislative acts here because they enact prospective policy concerning the city’s departments, offices and resources. The retaliatory-motive verdict does not transform those otherwise legislative functions into administrative acts or defeat absolute immunity.',
 'All nine join the complete classification, motive rule and bounded reversal.',
 'The budget anticipated reduced state aid, froze salaries and proposed eliminating 135 positions. The ordinance eliminated an entire department and its office prospectively, even though Scott-Harris was its sole employee. It therefore determined future structure and resource allocation as well as affecting the incumbent. Forrester’s individualized administrative personnel decision is materially different. The Court examines substance as well as formal enactment and does not decide whether formal legislative character alone would suffice in another case. Once this function is correctly classified, Tenney’s protection cannot depend on a jury’s assessment of motive. Fletcher likewise separates protected function from allegedly improper purpose; its personal-attestation exception illustrates that different acts remain independently classified. The jury’s rejection of racial discrimination and finding of retaliation are not reweighed. Immunity does not declare the acts constitutional. Separate administrative execution, personal discharge decisions outside this lawmaking function, ministerial enforcement and unclassified threats receive no automatic protection.')],
 precedent='- Tenney supplies protection of the legislative process and the rule that improper motive does not defeat immunity for legislative acts.\n- Lake Country Estates supports function-based legislative immunity below the state-legislature level; the principle extends here to local lawmaking.\n- Consumers Union supports equivalent protection for executive participation in the legislative function.\n- Antoine preserves the obligation of the official claiming immunity to establish historical and functional justification; importance or office alone remains insufficient.\n- Forrester’s administrative personnel action is distinguished from prospective abolition of a department and office.\n- Fletcher preserves separate classification of actual functions and the motive/function distinction. Richardson’s different private-prison setting does not negate historically supported public legislative immunity. Clinton’s function-based analysis is consistent, but its distinct presidential constitutional rationale is unnecessary here.',
 law='Absolute legislative immunity defeats the reviewed personal damages claims for these local legislative acts. The functional inquiry remains necessary, and the Court leaves formal legislative character alone undecided. The decision creates no general personnel immunity, municipal absolute immunity or defense for all administrative implementation.',
 separate='',
 procedure='This Supreme Court review is complete. The lower courts must give effect to the officials’ absolute immunity on the reviewed legislative damages claims. No liability or proximate-cause ruling is needed, no additional evidentiary hearing is directed and no claim against a nonpetitioning defendant is restored.',
 sources='The budget, ordinance, trial verdicts, post-verdict immunity ruling and appellate posture are reported in [523 U.S. 44](https://www.govinfo.gov/content/pkg/USREPORTS-523/pdf/USREPORTS-523-44.pdf). The city-council vote was a municipal act, distinct from this Court’s vote. The jury’s retaliation finding is accepted for the immunity issue; it is not a new merits finding by this Court. The full trial record and original pleadings are not separately reproduced.',
 stone='The October 21, 2026 approved position expressly reverses the individual damages ruling for introducing the budget, voting and signing the ordinance, preserves immunity despite alleged improper motive, and excludes separate nonlegislative execution. The complete shared rule fits those terms. The prospective policy/office character explains why these acts are legislative without adding a universal additional test. Stone joins in full; no fallback or changed core is used.',
 continuity='No material separate writing or new Supreme Court return condition. Aponte’s retained qualified-immunity result does not displace absolute legislative immunity. March 3 peers, including pending Kawaauhau, share the entering-law baseline and supply no law to this decision.'
)
D['lexecon'] = dict(
 case='Lexecon Inc. v. Milberg Weiss Bershad Hynes & Lerach', docket='No. 96-1482', date='1998-03-03', audit=5, slice='12_LEXECON',
 result='Reversed and remanded, 9–0; section 1407 forbids the self-transfer and requires return of the continuing action, with the pretrial dispositions kept distinct.',
 event='Lexecon Inc. v. Milberg Weiss Bershad Hynes & Lerach, No. 96-1482. Plenary merits decision, March 3, 1998; argued November 10, 1997. On writ of certiorari under 28 U.S.C. §1254(1) to the Ninth Circuit. The question is whether an MDL transferee court may use 28 U.S.C. §1404(a) to assign a transferred action to itself for trial despite §1407(a)’s remand command. Lexecon’s Illinois diversity tort action was transferred to Arizona for coordinated pretrial proceedings. The Arizona court entered pretrial dispositions, denied requests to suggest remand and retained the defamation claim for a defense trial judgment; the Ninth Circuit sustained the self-transfer. Lexecon preserved the objection through remand requests, mandamus and direct appeal.',
 action='The Ninth Circuit’s judgment is reversed and the case remanded for enforcement of the statutory return obligation and treatment of properly remaining appellate issues.',
 judgment='**Reverse and remand, 9–0.**\n\n**Supporting:** '+names(ALL)+'.\n\nThe defamation trial judgment resulting from the preserved unlawful self-transfer must be set aside and the continuing action returned to the originating district through the proper §1407 process. The authorized pretrial summary judgments, including the distinct Cotchett Rule 54(b) judgment, are not automatically void; their properly remaining appellate issues retain their own posture. Stone-Zsela agrees with the ancillary dispositions described in Part III without adding a ground.',
 topology='| Writing | Author | Joined by | Relationship to judgment | Scope joined |\n|---|---|---|---|---|\n'
 '| Opinion of the Court | {author} | {joiners} | Reverses and remands | All eight Associate Justices join Parts I–III; Stone-Zsela joins Parts I–II on statutory return and the trial-forum remedy, and agrees only with Part III’s ancillary dispositions |\n\n'
 'The opinion rests on text, structure and the preserved objection. It adds no legislative-history rationale. No separate writing issues.',
 holdings=[H('I. The MDL transferee cannot defeat mandatory return through self-transfer',
 'Unless the transferred action has previously terminated, §1407(a) requires the Panel to remand it to the original district at or before completion of coordinated pretrial proceedings. Section 1404(a) does not authorize the transferee court to retain that continuing action for trial by transferring it from itself to itself.',
 'Part I is joined by all nine Justices and supplies direct statutory authority.',
 'Section 1407 authorizes coordination for pretrial proceedings and commands return of each continuing action. The Panel may separate and remand particular claims earlier; an action that has actually terminated needs no return. Changing the asserted venue basis does not terminate the action. Addressing the command to the Panel does not authorize the transferee court to prevent its performance. Section 1404(a)’s general permission to transfer to another eligible district or division coexists with, rather than defeats, this specific temporary allocation. Section 1407(f) permits only rules consistent with Acts of Congress, so the cited self-assignment practice cannot alter the return obligation. Subsection (h)’s specific Clayton Act trial-transfer authorization does not confer that power in this tort action. The investment in coordinated pretrial work is substantial, but efficiency cannot delete the enacted sequence. A later lawful transfer by the proper court and consent or waiver questions not presented remain open.'),
 H('II. The preserved trial-forum error requires correction of this judgment',
 'A party that preserved its §1407 return objection need not prove that a different jury would have reached a different verdict to obtain correction of the resulting unauthorized trial forum. This uncured violation requires setting aside the defamation trial judgment and enforcing statutory remand.',
 'Part II is joined by all nine Justices; its remedy follows the mandatory return right asserted here.',
 'Lexecon repeatedly requested remand, sought mandamus and then pursued the promised direct appeal. The possibility that Arizona could originally have been a proper venue does not supply the procedure Congress required after an MDL transfer. Caterpillar preserves a completed judgment when the jurisdictional defect actually disappeared before trial; the prohibited retention for this trial never received an equivalent cure. Good Real Property rejects inventing dismissal of a substantive action as a sanction for administrative delay. This case instead directly enforces a particular allocation of the trial forum without extinguishing the cause of action. No constitutional or subject-matter-jurisdiction label is necessary, and the Court adopts no universal rule that every procedural error defeats a completed judgment. The statutory return must occur before any independently lawful later transfer; no permanent right against such a transfer is adjudicated.'),
 H('III. Authorized pretrial work and unreviewed tort issues remain separate',
 'The improper self-transfer does not automatically invalidate decisions made within authorized pretrial proceedings or decide the merits of the underlying tort claims. Properly remaining appellate challenges must be addressed in their own posture; the unpreserved request for prospective application does not alter this disposition.',
 'Part III is joined by all eight Associate Justices. Stone-Zsela agrees with these dispositions without joining an additional rationale.',
 'The malicious-prosecution and abuse-of-process rulings and the Cotchett Rule 54(b) judgment are pretrial dispositions, not the defamation trial verdict. Lexecon disputed the Rule 54(b) exercise of discretion without denying power to enter an authorized pretrial judgment. Those distinctions prevent wholesale reinstatement of every claim merely because trial retention was unlawful. The argument that the defamation claim should independently have been dismissed before trial remains for proper consideration, not a new factual or tort-law ruling here. The prospectivity request was not presented below or in opposition to review and supplies no basis for a different result in this case. No comprehensive retroactivity doctrine, new waiver finding or adjudication of a later transfer is adopted.')],
 precedent='- Caterpillar’s completed-judgment protection requires an actual pretrial cure; the preserved trial-forum defect here is distinguished as uncured. Its statutory remand duty remains mandatory.\n- Good Real Property preserves mandatory administrative duties while rejecting an unstated forfeiture-dismissal sanction; direct enforcement of the specified trial allocation is different.\n- City of Chicago retains the distinction between statutory power and convenience or discretionary retention; it supplies no authority to enlarge §1407’s temporary pretrial grant.',
 law='Section 1407’s return command cannot be displaced by a transferee’s §1404 self-transfer. Authorized pretrial adjudication remains distinct from unauthorized trial retention, and a preserved objection secures the statutory forum remedy without independent proof that the verdict would differ. No general subject-matter-jurisdiction invalidity, bar on consensual arrangements or decision about a later lawful transfer follows.',
 separate='',
 procedure='The case returns for proceedings consistent with mandatory remand to the Northern District of Illinois and correction of the defamation trial judgment. The proper courts must keep the distinct pretrial and remaining appellate issues separate. The Court decides no tort liability, automatic new verdict or permanent prohibition on lawful later transfer. This Supreme Court review is complete.',
 sources='The transfer, preservation history, trial and distinct pretrial judgments are reported in [523 U.S. 26](https://www.govinfo.gov/content/pkg/USREPORTS-523/pdf/USREPORTS-523-26.pdf). Sections 1404 and 1407 appear in the official 1997 United States Code. The decision uses the enacted statutory text and the reported contemporary rule argument; later Panel rule revisions supply no premise. The original motions, trial record and complete briefs are not separately reproduced, and no additional waiver or trial error is inferred.',
 stone='The October 21, 2026 approved supplement expressly supports mandatory return, rejection of section 1404 self-transfer, reversal/remand and a lawful post-return transfer boundary. Stone therefore joins Parts I–II and the trial-forum remedy. Part III’s independent pretrial-appeal, tort-defense and unpreserved-prospectivity matters are not expressly addressed; the approved standing fallback supplies their dispositions only, without rationale or full-opinion authorship eligibility. No substantive waiver, consent or later-transfer ruling is attributed to him. No separate writing is needed because exact joins preserve every approved limit.',
 continuity='No separate opinion is published. Stone’s Part III judgment-only relationship is stated in the topology and supplies no additional public doctrinal proposition. Scalia joins all actual parts because no legislative-history proposition is included; this does not change his frozen refusal to join such a rationale. March 3 peers supply no entering law.'
)
D['spencer'] = dict(
 case='Spencer v. Kemna', docket='No. 96-7171', date='1998-03-03', audit=6, slice='11_SPENCER',
 result='Affirmed for mootness, 8–1; custody existed at filing, but no actual continuing injury or applicable exception sustains this expired-revocation habeas action.',
 event='Spencer v. Kemna, No. 96-7171. Decision after plenary review, March 3, 1998; argued November 12, 1997. On writ of certiorari under 28 U.S.C. §1254(1) to the Eighth Circuit, which affirmed dismissal of the §2254 petition. Spencer challenges the September 1992 parole revocation, not the original burglary and stealing convictions. He filed on April 1, 1993 while imprisoned under the revocation; the challenged sentence expired October 16, 1993. Review concerns statutory custody, continuing Article III injury, mootness exceptions and the asserted effect of possible civil-remedy limits.',
 action='The Eighth Circuit’s judgment affirming dismissal is affirmed on mootness alone.',
 judgment='**Affirm dismissal as moot, 8–1.**\n\n**Supporting:** Stone-Zsela, O’Connor, Scalia, Kennedy, Souter, Thomas, Ginsburg and Breyer.\n**Opposing:** Stevens.\n\nThe dismissal rests on absence of a continuing Article III controversy, not failure of custody when the petition was filed or a decision on the revocation’s merits. Stevens would reverse and remand the live petition for its remaining lawful adjudication. Stone-Zsela agrees with the ancillary custody-at-filing, capable-of-repetition exception, litigation-delay and civil-remedy dispositions without adding a ground.',
 topology='| Writing | Author | Joined by | Relationship to judgment | Scope joined |\n|---|---|---|---|---|\n'
 '| Opinion of the Court | {author} | {joiners} | Affirms mootness dismissal | O’Connor, Scalia, Kennedy, Souter, Thomas, Ginsburg and Breyer join all parts; Stone-Zsela joins Part II’s actual-continuing-injury ground and mootness result, but agrees only with Part II’s capable-of-repetition and litigation-delay dispositions and Parts I and III’s ancillary dispositions, without those additional rationales |\n'
 '| Dissent | Stevens | — | Would reverse and remand | Recognizes the particular official adverse adjudication’s continuing reputational consequence; does not decide the revocation merits or an affirmative section 1983 exception |',
 holdings=[H('I. Custody at filing and a continuing controversy are separate requirements',
 'Section 2254’s custody requirement is satisfied when the petitioner is held under the challenged revocation at filing; later expiration does not retroactively defeat that threshold. Article III nonetheless requires a concrete continuing injury after the challenged sentence expires.',
 'Part I is joined by O’Connor, Scalia, Kennedy, Souter, Thomas, Ginsburg and Breyer, seven direct votes. Stone-Zsela agrees with the custody disposition without an additional ground; Stevens also accepts custody at filing.',
 'Spencer was imprisoned under this revocation on April 1, 1993. The District Court’s alternative suggestion that expiration removed statutory custody is incorrect. The later seven-year imprisonment arises from an unrelated conviction, rather than the unexpired consecutive aggregate addressed in Garlotte. A timely filing therefore satisfies the statutory entry condition without itself supplying an enduring constitutional controversy. Lujan and Arizonans require an actual personal interest throughout adjudication, not simply an interest that existed when suit began.'),
 H('II. The asserted collateral consequences and exceptions do not keep this petition live',
 'After this parole-revocation sentence expires, collateral injury is not presumed merely from the revocation; the petitioner must show an actual continuing consequence redressable in this action. Speculative future parole, sentencing or evidentiary uses, the possibility of recurrence and litigation delay do not supply that showing on this record.',
 'Part II’s continuing-injury rule and mootness result have eight direct joins: Stone-Zsela and the seven Associates joining the Court opinion. The seven Associates also directly adopt the specific exception and delay applications.',
 'An attack on a conviction is distinct from this challenge to a revocation of an otherwise valid sentence. Lane supports examining the actual surviving interest, although Spencer, unlike Lane’s respondents, challenges the adverse revocation finding itself. Future parole use depends on discretionary treatment, sentencing use on later legal developments, impeachment on future testimony and permissible use, and other-crimes evidence on additional contingencies. No present mandatory disability or demonstrated imminent adverse use is established. MacArthur’s actual statutory information interest and existing damages action do not make every retained adverse record a live habeas controversy; the Court adopts no categorical exclusion of reputational injury. The capable-of-repetition exception requires both a duration too short for full review and a reasonable expectation that this claimant will again face the action. Neither the asserted delay nor possible injury to others establishes those conditions. State extensions and delayed judicial action cannot create Article III power through fault or estoppel. Expiration occurred by the sentence’s terms, not a newly established strategic cessation. The Court decides no revocation claim, criminal guilt or exoneration.'),
 H('III. An unresolved future civil remedy does not create this habeas controversy',
 'Heck and Edwards do not establish an unavoidable favorable-invalidation bar for every former prisoner: their controlling rules expressly reserve that category and persons without a realistic lawful custody-review opportunity. The unresolved scope of a possible later civil action does not create a damages claim in this habeas case or dispense with continuing Article III injury.',
 'Part III is joined by O’Connor, Scalia, Kennedy, Souter, Thomas, Ginsburg and Breyer, seven direct votes. Stone-Zsela agrees with the disposition of this ancillary contention without adding a ground.',
 'Heck’s decided prerequisite concerns the specified in-custody, conviction-negating damages claim; Edwards preserves that limit while requiring genuinely independent injuries to be classified by their consequences. Neither decision supplies the universal former-prisoner bar assumed by Spencer’s argument. A claim whose success does not necessarily invalidate the revocation would also require its own analysis. The Court need not choose an affirmative former-prisoner exception to reject the asserted inevitable bar. No damages claim is pleaded here, and possible difficulty obtaining another remedy does not empower the Court to decide an otherwise moot habeas petition. The existing reservations remain open rather than becoming either a categorical bar or a newly adjudicated exception.')],
 precedent='- Lane is applied for the continuing-interest inquiry while its unchallenged-revocation posture is distinguished; no automatic consequence is inferred for this revocation.\n- Lujan and Arizonans preserve an actual personal controversy throughout review. Arizonans’ vacatur remedy does not require clearing a nonexistent intervening merits judgment here.\n- Garlotte’s continuous consecutive-sentence aggregate is distinguished from Spencer’s unrelated later custody; custody at filing remains sufficient for the statutory threshold.\n- MacArthur preserves supported actual personal information interests without creating a universal reputation-based habeas rule.\n- Heck and Edwards retain their bounded invalidation prerequisite and express former-prisoner/realistic-opportunity reservations; no affirmative section 1983 exception or universal bar is added.',
 law='A timely custody-based habeas filing does not survive expiration of the challenged sentence without continuing Article III injury or a valid exception. This record establishes neither. The revocation’s merits remain unadjudicated, and the separate civil-remedy questions expressly reserved by Heck and Edwards remain open.',
 separate='**Stevens, dissenting.** Stevens distinguishes Lane because Spencer challenges the official adverse revocation finding itself, not merely completed custody while leaving that finding untouched. He considers the particular government adjudication and the State’s continuing reliance on the incorporated serious-misconduct report a present personal reputational consequence that invalidation could meaningfully remove. He does not presume every revocation carries statutory disabilities or depend on a future crime, audience reaction or invented damages claim. The written order found condition violations and incorporated a report; it was not an express rape conviction, and the State’s characterization remains distinct. MacArthur’s requirement of a supported personal interest does not, in his view, erase this already imposed official determination. He would remand for unresolved lawful adjudication, without granting a writ, finding procedural wrongdoing or deciding the civil-remedy question.',
 procedure='The habeas action remains dismissed as moot, without constitutional-merits preclusion. No writ, new revocation hearing, expungement, damages or exoneration is ordered. This Supreme Court review is complete, and no continuing return condition is created.',
 sources='The revocation order, incorporated report, custody dates, claimed procedural defects and later separate sentence are reported in [523 U.S. 1](https://www.govinfo.gov/content/pkg/USREPORTS-523/pdf/USREPORTS-523-1.pdf). The woman’s allegations, Spencer’s admitted cocaine use and denial of force, the written condition-violation order and the State’s description remain distinct. The underlying reports and complete record are available here through published recitations; they establish no criminal conviction for the alleged conduct. No reputation-only submission or damages demand by Spencer is attributed to him. [Lane, 455 U.S. 624](https://www.govinfo.gov/content/pkg/USREPORTS-455/pdf/USREPORTS-455-624.pdf), supplies the earlier posture and continuing-interest analysis.',
 stone='The approved October 21, 2026 supplement affirms mootness because an expired parole-revocation sentence requires actual continuing injury and hypothetical future uses do not necessarily supply it; an attack on conviction is distinct. Stone joins Part II at that stated level and its no-merits disposition. His standing fallback supplies only the dispositions on statutory custody at filing, the specifically asserted exceptions/delay arguments to the extent unaddressed, and the ancillary Heck contention; no exception details or affirmative civil-remedy proposition are attributed to him. He is not eligible to author the complete rationale through fallback. No new reopening mechanism, collateral consequence or revocation merits is invented.',
 continuity='Stevens’s published dissent supplies the only noncontrolling position and is fully stated in Public Projection. The narrower existing Heck/Edwards premises explain why O’Connor, Souter, Ginsburg and Breyer join preservation of the existing reservation rather than publish an affirmative former-prisoner exception. No new damages case or Supreme Court return is created.'
)

BLOCKS=['Event','Participation','Public Action','Judgment & Remedy','Opinion Topology','Holdings','Precedent Treatment','Law After Decision','Separate Writings','Procedure After Action','Source Notes']
def read(p): return p.read_text(encoding='utf-8-sig')
def slug(s):
 import unicodedata
 s=unicodedata.normalize('NFKD',s).encode('ascii','ignore').decode()
 return re.sub(r'[^a-z0-9]+','_',s.lower()).strip('_')
def frozen_audit(d):
 if not d['audit']:
  s=read(TERM/'freeze/OT_1997CHUNK4_NCUA_RECONCILED.md')
  a=s.index('## Reconciliation result'); b=s.index('## Source-read and integrity receipt')
  return s[a:b]
 s=read(TERM/'freeze/OT_1997CHUNK4_B_RECONCILED.md')
 a=s.index(f"## {d['audit']}.")
 nexthead=f"## {d['audit']+1}."
 b=s.index(nexthead,a) if nexthead in s[a:] else s.index('## Reconciliation source',a)
 piece=s[a:b]
 labels={1:'Venetie',2:'Aponte',3:'Shahar',4:'Bogan',5:'Lexecon',6:'Spencer'}
 a=s.index('### '+labels[d['audit']]); b=s.find('\n### ',a+1)
 if b<0 or b>s.index('## Complete reconciled'):b=s.index('## Complete reconciled')
 return s[a:b]+'\n'+piece + ('\n**Historical departure:** The historical civil-remedy concurrences of O’Connor, Souter, Ginsburg and Breyer advocated an affirmative former-prisoner section 1983 route. Here Heck’s controlling bounded in-custody rule and Edwards’s express reservations leave no general former-prisoner bar to overcome. O’Connor authored that narrower statutory-coordination rule, Souter joined that rationale, Ginsburg joined the bounded operative rule and Breyer joined Edwards’s preservation. Each therefore joins preservation of the actual unresolved category without deciding an unpleaded civil action; no affirmative exception or contrary bar is adopted.\n' if d['audit']==6 else '')
def render_record(key, assignment):
 d=D[key]
 author=assignment['author']
 eligible=assignment['eligible']
 coalition=assignment['lead_coalition']
 topology=d['topology'].format(author=author,joiners=names([x for x in coalition if x!=author]))
 vals=[d['event'], 'Chief Justice Stone-Zsela and Justices Stevens, O’Connor, Scalia, Kennedy, Souter, Thomas, Ginsburg and Breyer participate. No Justice is recused.',d['action'],d['judgment'],topology,'\n\n'.join(d['holdings']),d['precedent'],d['law'],d['separate'],d['procedure'],d['sources']]
 public='\n\n'.join('## '+h+'\n\n'+v for h,v in zip(BLOCKS,vals)).rstrip()+'\n'
 auditfile='OT_1997CHUNK4_NCUA_RECONCILED.md' if not d['audit'] else 'OT_1997CHUNK4_B_RECONCILED.md'
 audithash=hashlib.sha256((TERM/'freeze'/auditfile).read_bytes()).hexdigest()
 counts='; '.join(f'{j} {assignment["counts"][j]}' for j in ALL)
 statement=(f"**Form fixed first:** {assignment['form']}. See `freeze/OT_1997CHUNK4_B_FORM_FIRST.md`; governing propositions were fixed before counts or an author.\n\n"
  f"**Assignment authority:** {assignment['authority']}\n\n**Before-assignment counts:** {counts}.\n\n"
  f"**Last counted event:** {assignment['last_counted']}.\n\n**Eligible authors:** {names(eligible)}.\n\n"
  f"**Balance pool:** {names(assignment['pool'])}. The pool contains eligible authors no more than one above the eligible minimum.\n\n"
  f"**Author selected:** {author}. {assignment['fit']}\n\n"
  f"**Recount evidence:** `{assignment['evidence']}` copies actual preceding Record opinion topologies; `{assignment['receipt']}` records the individually reviewed classifications. All current signed plenary merits leads are recounted from those actual topologies, including earlier Records in this Run; no prior assignment tally supplies a count. {assignment['count_effect']}\n\n"
  "**Final compatibility:** Each actual join is tested against the frozen reconciled commitments and Stone’s approved scope. No circulated draft or changed non-Stone commitment is invented. The actual opinion omits grounds its joiners do not adopt; the public topology preserves all remaining partial joins and nonreach. Separate authorship is selected for the stated legal disagreement, not imported from the comparator or counted toward the balance.")
 rec=(f"**Case and dockets:** {d['case']}; {d['docket']}.\n**Event and date:** {'Decision after plenary review' if key=='spencer' else 'Plenary merits decision'}; {d['date']}; October Term 1997; chunk 4.\n**Result:** {d['result']}\n**Version / lineage:** Original decision.\n\n"
  f"# {d['case']}\n\n## Event, channel and chronology\n\n{d['event']}\n\n"
  "The matter enters this stage for plenary review under the approved term placement; no historical certiorari poll or invented grant date supplies a vote. The historical merits matters retain their supplied argument and delivery anchors; the lower-court additions are submitted under the supplied scheduling authority without inventing oral argument. All six preceding chunk-4 A Records were completed before any B assignment. Chronology and actual public-law gates are recorded in the B assembly validation. Uncoordinated same-day events share their entering-law baseline; assignment ordering alone does not make one another’s law. Pending Kawaauhau is neither completed law nor a counted opinion.\n\n"
  f"## Participation and law entering\n\nAll nine listed Justices are seated at argument or submission and at decision. No case-specific nonparticipation is established in the frozen packet, and no recusal is inferred from historical absences. The quorum of six is satisfied; a controlling proposition requires five of nine. The Supreme Court channel is 28 U.S.C. §1254(1); the issue-specific lower action and review limits remain those stated above.\n\n"
  f"The authority reading copy is `entering-law/OT_1997CHUNK4_{d['slice']}.md`, with the NCUA statutory or Shahar association/religion supplement where applicable. The opening trackers through OT1996 and actual current-term holdings control; the slice is not independent authority. The full issue-specific rules, limits, prior-law treatment and post-action law are stated in the identical controlling-holdings kernel and Public Projection below. The frozen neutral packet is `freeze/OT_1997CHUNK4_MODEL_B_NEUTRAL.md`.\n\n"
  f"## Stone approval and final scope\n\n{d['stone']}\n\n"
  f"## Judgment, opinions and controlling-holdings kernel\n\n{d['judgment']}\n\n{topology}\n\n"+'\n\n'.join(d['holdings'])+'\n\n'
  f"### Precedent treatment and resulting law\n\n{d['precedent']}\n\n{d['law']}\n\n"
  f"## Published continuity and procedure\n\n{d['continuity']}\n\n{d['procedure']}\n\n"
  f"## Sources, cutoff and bounded limitations\n\nResearch cutoff: {d['date']}. The source mapping is the frozen neutral packet and the applicable sections of `research/chunk4_control/NEUTRAL_FACTS.md`, `NEUTRAL_FACTS_ADDITIONAL.md`, or `research/chunk4_lower/SOURCE_REPORT.md` and `SHAHAR_NEUTRAL_FACTS.md`. Earlier full-reading receipts establish the described source coverage; this assembly uses those scoped reports and the full frozen reconciliation rather than claiming a new reading of unavailable original filings. Published historical recitations establish the objective record; the current law and final coalitions are distinct simulation judgments. No later amendment, pending peer outcome or unsupported material fact enters.\n\n{d['sources']}\n\n"
  f"## Adaptive audit annex\n\n### Frozen provenance and all-eight-Justice audit\n\nThe following bounded extract reproduces the final reconciliation’s individual commitments, grounds, alternatives and limits. Statements describing an earlier context’s source access refer to that completed stage. It does not itself assign authors or supersede the final topology above. Authority: `freeze/{auditfile}`, SHA-256 `{audithash}`; the independent commitment freeze remains unchanged.\n\n{frozen_audit(d)}\n\n"
  f"### Assignment and final join validation\n\n{statement}\n\n"
  f"## Validation status\n\nAssembly verified exact docket/claim scope, lawful channel, supplied chronology, participation at both milestones, quorum, disposition and proposition arithmetic, Stone’s fixed core and fallback boundaries, all eight reconciled commitments, source-specific limits, direct majority authority, remedies and nonreach. The substantive holdings above are copied unchanged into the Public Projection. Each controlling explanation is below 350 words. A per-record deterministic receipt records exact eleven-block order, identical holdings, explanation length and file identity; the coordinated chunk checker and workspace projection are integration tasks and are not falsely certified here. No unresolved matter-specific blocker remains. Durable path: `records/{slug(d['case'].split(' / ')[0])}_{'mootness' if key=='spencer' else 'merits'}_{d['date']}.md`. Current-Term-State commitment follows the parent’s coordinated validation and manifest/ledger rebuild, not an invented Git event.\n\n## Public Projection\n\n{public}")
 return rec
def main():
 ap=argparse.ArgumentParser(); ap.add_argument('key',choices=D);ap.add_argument('--assignment',type=Path,required=True);args=ap.parse_args()
 assignment=json.loads(read(args.assignment));d=D[args.key]
 assert assignment['chronology_gate']=='A complete; six preceding Records verified'
 assert assignment['author'] in assignment['eligible'] and assignment['author'] in assignment['pool']
 assert set(assignment['counts'])==set(ALL)
 minimum=min(assignment['counts'][j] for j in assignment['eligible'])
 assert assignment['pool']==[j for j in assignment['eligible'] if assignment['counts'][j]<=minimum+1]
 p=TERM/'records'/f"{slug(d['case'].split(' / ')[0])}_{'mootness' if args.key=='spencer' else 'merits'}_{d['date']}.md"
 assert not p.exists(), f'Existing Record must never be silently rewritten: {p}'
 content=render_record(args.key,assignment)
 pub=content.split('## Public Projection\n\n',1)[1]
 assert re.findall(r'^## (.+)$',pub,re.M)==BLOCKS
 for h in d['holdings']:
  n=len(h.split('**Controlling explanation:** ',1)[1].split());assert n<=350,(args.key,n)
 assert content.count('\n\n'.join(d['holdings']))==2
 assert not re.search(r'(?i)simulated|user-directed|approved|SHA-256|reconciliation|freeze/|fallback|modeling|workflow',pub)
 p.write_text(content,encoding='utf-8',newline='\n')
 receipt={'record':str(p.relative_to(TERM)), 'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'blocks':BLOCKS,'holdings_identical':True,'explanation_words':[len(h.split('**Controlling explanation:** ',1)[1].split()) for h in d['holdings']],'assignment':str(args.assignment),'status':'record-local deterministic checks passed; integration checks pending'}
 (TERM/'freeze'/f'OT_1997CHUNK4_{args.key.upper()}_RECORD_CHECK.json').write_text(json.dumps(receipt,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
 print(json.dumps(receipt,ensure_ascii=False,indent=2))
if __name__=='__main__':main()
